    ["Saved on this computer only. Only the last four characters are ever shown."] = "Yalnızca bu bilgisayarda kaydedilir. Yalnızca son dört karakter gösterilir.",
    ["Convai free tier: daily limit reached"] = "Convai (ücretsiz plan): günlük limit doldu",
    ["Convai free tier: limit used up"] = "Convai (ücretsiz plan): limit doldu",
    ["The clipboard could not be read."] = "Pano okunamadı.",
    ["The clipboard does not hold a Convai API key."] = "Panoda bir Convai API anahtarı yok.",
    ["The clipboard is empty. Copy your key first."] = "Pano boş. Önce anahtarını kopyala.",
