    ["The request could not be sent. Try again."] = "Talep gönderilemedi. Tekrar dene.",
    ["Convai free tier: {left} of {limit} left today"] = "Convai (ücretsiz plan): bugün {limit} hakkın içinden {left} kaldı",
    ["Your key was removed."] = "Anahtarın kaldırıldı.",
