    ["Mistral cloud voice (Voxtral)"] = "Mistral bulut sesi (Voxtral)",
    ["{voice} · needs Mistral key"] = "{voice} · Mistral anahtarı gerekir",
    ["Loading the OmniVoice voice…"] = "OmniVoice sesi yükleniyor…",
    ["OmniVoice voice is ready."] = "OmniVoice sesi hazır.",
    ["OmniVoice could not load. See Help in Settings."] = "OmniVoice yüklenemedi. Ayarlar'daki Yardım'a bak.",
    ["Loading the Pocket voice…"] = "Pocket sesi yükleniyor…",
    ["Pocket voice is ready."] = "Pocket sesi hazır.",
    ["Pocket voice"] = "Pocket sesi",
    ["The Pocket voice (V’s voice, and a companion’s when you chose Pocket) could not start, so it stays silent. Pocket is part of the Runtime: nothing else needs installing. Restart the game. If it happens again, generate a report below and send it."] = "Pocket sesi (V’nin sesi ve Pocket’ı seçtiysen bir yoldaşın sesi) başlatılamadı, bu yüzden sessiz kalıyor. Pocket, Runtime’ın bir parçasıdır; başka bir şey kurman gerekmez. Oyunu yeniden başlat. Sorun tekrar ederse Yardım’daki “Rapor oluştur” düğmesiyle bir rapor oluşturup gönder.",
    ["Windows blocked a file that the Pocket voice needs (Smart App Control or an Application Control policy), so Pocket cannot run on this PC. Choose another voice in Settings, such as OmniVoice or a cloud voice."] = "Windows, Pocket sesinin ihtiyaç duyduğu bir dosyayı engelledi (Smart App Control veya bir Application Control ilkesi), bu yüzden Pocket bu bilgisayarda çalışamaz. Ayarlar’dan OmniVoice veya bir bulut sesi gibi başka bir ses seç.",
    ["Pocket could not load. See Help in Settings."] = "Pocket yüklenemedi. Ayarlar'daki Yardım'a bak.",
    ["Local AI is warming up…"] = "Local AI hazırlanıyor…",
    ["Local AI is ready."] = "Local AI hazır.",
    ["A few sentences the character keeps about your past talks. Edit them or clear them."] = "Karakterin geçmiş konuşmalarınla ilgili tuttuğu birkaç cümle. Bunları düzenle ya da temizle.",
    ["A line this character might say"] = "Bu karakterin söyleyebileceği bir satır",
    ["A memory cannot be empty."] = "Anı boş olamaz.",
