    ["Everyday people"] = "Sıradan insanlar",
    ["Everyday people do not keep memories of your talks."] = "Sıradan insanlar konuşmalarınla ilgili anı tutmaz.",
    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "Hepsi birlikte çok uzun. Toplamın {max} karakterin altında kalması için bir şeyi kısalt.",
    ["Example lines"] = "Örnek satırlar",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "Konuşurken karakterin fark ettiği bilgiler. Yanlış olanları değiştir ya da sil.",
    ["For example: V has a sister called Lena."] = "Örneğin: V'nin Lena adında bir kız kardeşi var.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "{name} için orijinal metne dönülsün mü? Bu karaktere yaptığın tüm değişiklikler kaldırılır.",
    ["Go back to the shipped text for {name}? Your changes to this part are removed."] = "{name} için orijinal metne dönülsün mü? Bu bölümdeki değişikliklerin kaldırılır.",
    ["How they sound: pace, attitude, favourite habits of speech."] = "Nasıl konuştukları: tempo, tavır, sevdikleri konuşma alışkanlıkları.",
    ["Lines in their voice. They show the tone only and are never said back word for word."] = "Karakterin sesiyle yazılmış satırlar. Yalnızca tonu gösterirler, asla kelimesi kelimesine tekrar edilmezler.",
    ["No match."] = "Eşleşme yok.",
    ["Nothing yet."] = "Henüz bir şey yok.",
    ["Opening the editor in your browser. Switch to your browser if it does not come to the front."] = "Düzenleyici tarayıcında açılıyor. Öne gelmezse tarayıcına geç.",
